1	// --- Price list: insurance values and base premiums ---
2	
3	/** The price list states one insurance value and one base premium per item kind. */
4	interface ListedPrice {
5	  insuranceValue: number;
6	  basePremium: number;
7	}
8	
9	const MAIN_ITEM_PRICE_LIST: Record<string, ListedPrice> = {
10	  sword: { insuranceValue: 1000, basePremium: 100 },
11	  amulet: { insuranceValue: 600, basePremium: 60 },
12	  staff: { insuranceValue: 800, basePremium: 80 },
13	  potion: { insuranceValue: 400, basePremium: 40 },
14	};
15	
16	const COMPONENT_PRICE: ListedPrice = { insuranceValue: 250, basePremium: 25 };
17	const COMPONENT_BLOCK_SIZE = 3;
18	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
19	
20	// --- Premium modifiers ---
21	const CURSE_SURCHARGE = 0.5;
22	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
23	const HIGH_ENCHANTMENT_LEVEL = 5;
24	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
25	const LOYALTY_DISCOUNT = 0.2;
26	const LOYALTY_YEARS = 2;
27	const FIRST_INSURANCE_SURCHARGE = 0.1;
28	const PROCESSING_FEE = 5;
29	
30	// --- Claim processing ---
31	const DEDUCTIBLE_PER_DAMAGE = 100;
32	const PAYOUT_CAP_MULTIPLE = 2;
33	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
34	const HALF_REIMBURSEMENT = 0.5;
35	
36	export interface Customer {
37	  yearsWithMHPCO: number;
38	}
39	
40	export interface Item {
41	  type: string;
42	  material?: string;
43	  enchantment?: number;
44	  cursed?: boolean;
45	}
46	
47	export interface QuoteStep {
48	  op: "quote";
49	  items: Item[];
50	}
51	
52	export interface Damage {
53	  itemType: string;
54	  amount: number;
55	}
56	
57	export interface Incident {
58	  cause: string;
59	  damages: Damage[];
60	}
61	
62	export interface ClaimStep {
63	  op: "claim";
64	  policy: number;
65	  incident: Incident;
66	}
67	
68	export type Step = QuoteStep | ClaimStep;
69	
70	export interface Scenario {
71	  customer: Customer;
72	  steps: Step[];
73	}
74	
75	export interface ScenarioResults {
76	  results: unknown[];
77	}
78	
79	const COMPONENT_TYPES = ["rune", "moonstone"];
80	
81	function isComponent(item: Item): boolean {
82	  return COMPONENT_TYPES.includes(item.type);
83	}
84	
85	/** Everything the price list prices individually, as opposed to by alike group. */
86	function isMainItem(item: Item): boolean {
87	  return item.type in MAIN_ITEM_PRICE_LIST;
88	}
89	
90	/** The MHPCO insures an item only if its type is named in the price list. */
91	function isInsurable(item: Item): boolean {
92	  return isMainItem(item) || isComponent(item);
93	}
94	
95	/**
96	 * Admission is the MHPCO's decision about what it is willing to cover at all,
97	 * taken before any pricing: an item the price list does not name cannot be
98	 * quoted, so the whole policy is refused.
99	 */
100	function admitToPolicy(items: Item[]): void {
101	  for (const item of items) {
102	    if (!isInsurable(item)) {
103	      throw new Error(`The MHPCO price list covers no item of type "${item.type}".`);
104	    }
105	  }
106	}
107	
108	/** Components are "alike" when they share a component type. */
109	function groupAlikeComponents(components: Item[]): Map<string, number> {
110	  const groupSizes = new Map<string, number>();
111	  for (const component of components) {
112	    const alikeness = component.type;
113	    groupSizes.set(alikeness, (groupSizes.get(alikeness) ?? 0) + 1);
114	  }
115	  return groupSizes;
116	}
117	
118	/** A building block of 3 alike components is offered at a special base premium. */
119	function alikeComponentGroupBasePremium(groupSize: number): number {
120	  return groupSize === COMPONENT_BLOCK_SIZE
121	    ? COMPONENT_BLOCK_BASE_PREMIUM
122	    : groupSize * COMPONENT_PRICE.basePremium;
123	}
124	
125	function mainItemsBasePremium(mainItems: Item[]): number {
126	  return mainItems.reduce((sum, item) => sum + MAIN_ITEM_PRICE_LIST[item.type].basePremium, 0);
127	}
128	
129	function componentsBasePremium(components: Item[]): number {
130	  let premium = 0;
131	  for (const groupSize of groupAlikeComponents(components).values()) {
132	    premium += alikeComponentGroupBasePremium(groupSize);
133	  }
134	  return premium;
135	}
136	
137	function policyBasePremium(items: Item[]): number {
138	  return (
139	    mainItemsBasePremium(items.filter(isMainItem)) +
140	    componentsBasePremium(items.filter(isComponent))
141	  );
142	}
143	
144	/**
145	 * An item-specific surcharge is a rate on the affected item's own base premium,
146	 * not on the policy's. Only main items carry a per-item base premium; a
147	 * component's belongs to its alike group, so the specification fixes no
148	 * surcharge for a cursed or highly enchanted component.
149	 *
150	 * Open question -- no example in the specification covers one, and no test
151	 * pins the outcome, so the behaviour here is undefined rather than decided:
152	 * the lookup misses and the premium becomes NaN. Settle it with a test before
153	 * relying on it; a quote is never reached with such an item today only because
154	 * no example produces one.
155	 */
156	function surchargeOnOwnBasePremium(item: Item, rate: number): number {
157	  return MAIN_ITEM_PRICE_LIST[item.type].basePremium * rate;
158	}
159	
160	function curseSurcharge(item: Item): number {
161	  return item.cursed === true ? surchargeOnOwnBasePremium(item, CURSE_SURCHARGE) : 0;
162	}
163	
164	/** An item is highly enchanted from enchantment level 5 upwards. */
165	function highEnchantmentSurcharge(item: Item): number {
166	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL
167	    ? surchargeOnOwnBasePremium(item, HIGH_ENCHANTMENT_SURCHARGE)
168	    : 0;
169	}
170	
171	/** Item-specific surcharges apply to the base premium of the affected item. */
172	function itemSurcharges(items: Item[]): number {
173	  return items.reduce(
174	    (sum, item) => sum + curseSurcharge(item) + highEnchantmentSurcharge(item),
175	    0,
176	  );
177	}
178	
179	/** A customer is long-standing from 2 years of business with MHPCO onwards. */
180	function loyaltyDiscount(basePremium: number, customer: Customer): number {
181	  return customer.yearsWithMHPCO >= LOYALTY_YEARS ? basePremium * LOYALTY_DISCOUNT : 0;
182	}
183	
184	/**
185	 * Every item in a quote is treated as a first insurance, regardless of customer
186	 * history, so the initial assessment surcharge carries no condition.
187	 */
188	function firstInsuranceSurcharge(basePremium: number): number {
189	  return basePremium * FIRST_INSURANCE_SURCHARGE;
190	}
191	
192	/** Customers receive a discount on each contract after their first. */
193	function followUpContractDiscount(basePremium: number, contractOrdinal: number): number {
194	  return contractOrdinal > 1 ? basePremium * FOLLOW_UP_CONTRACT_DISCOUNT : 0;
195	}
196	
197	/** Policy-wide modifiers apply to the policy base premium (the sum of all item base premiums). */
198	function policyWideModifiers(
199	  basePremium: number,
200	  customer: Customer,
201	  contractOrdinal: number,
202	): number {
203	  return (
204	    firstInsuranceSurcharge(basePremium) -
205	    loyaltyDiscount(basePremium, customer) -
206	    followUpContractDiscount(basePremium, contractOrdinal)
207	  );
208	}
209	
210	/** Rounding always favours the MHPCO; for a premium that means rounding up. */
211	function premiumRoundedInMHPCOsFavour(premium: number): number {
212	  return Math.ceil(premium);
213	}
214	
215	/**
216	 * The MHPCO prices a policy in one order: the policy base premium, then the
217	 * modifiers at their own scopes, then the processing fee at the very end.
218	 * Item-specific modifiers are charged against the base premium of the affected
219	 * item; policy-wide modifiers against the policy base premium. Only this final
220	 * amount is rounded -- intermediate amounts stay fractional.
221	 */
222	function quotePremium(items: Item[], customer: Customer, contractOrdinal: number): number {
223	  admitToPolicy(items);
224	  const basePremium = policyBasePremium(items);
225	  return premiumRoundedInMHPCOsFavour(
226	    basePremium +
227	      itemSurcharges(items) +
228	      policyWideModifiers(basePremium, customer, contractOrdinal) +
229	      PROCESSING_FEE,
230	  );
231	}
232	
233	/**
234	 * How many contracts the customer has taken out with MHPCO up to and including
235	 * the quote at this step. Every step is a quote today, so a step's position in
236	 * the scenario is its contract ordinal.
237	 */
238	function contractOrdinalOfStep(stepIndex: number): number {
239	  return stepIndex + 1;
240	}
241	
242	/** What the MHPCO would have to pay out if every insured item were destroyed. */
243	function insuranceSum(items: Item[]): number {
244	  return items.reduce(
245	    (sum, item) =>
246	      sum +
247	      (isComponent(item)
248	        ? COMPONENT_PRICE.insuranceValue
249	        : MAIN_ITEM_PRICE_LIST[item.type].insuranceValue),
250	    0,
251	  );
252	}
253	
254	/** A policy created by a quote step: what it covers, and how much cap is left. */
255	interface Policy {
256	  insuredItems: Item[];
257	  remainingCap: number;
258	}
259	
260	function openPolicy(items: Item[]): Policy {
261	  return { insuredItems: items, remainingCap: insuranceSum(items) * PAYOUT_CAP_MULTIPLE };
262	}
263	
264	/** Damage to a highly enchanted item is reimbursed at half the damage amount. */
265	function isHalfReimbursed(item: Item): boolean {
266	  return (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
267	}
268	
269	/** The share of a damage the MHPCO reimburses before the deductible is taken. */
270	function reimbursableDamage(damage: Damage, damagedItem: Item): number {
271	  return isHalfReimbursed(damagedItem) ? damage.amount * HALF_REIMBURSEMENT : damage.amount;
272	}
273	
274	/**
275	 * The deductible is the claimant's own share of each damage event: the MHPCO
276	 * reimburses what the damage exceeds it by.
277	 *
278	 * Adopted reading -- the specification says only that "a deductible of 100 G
279	 * applies per damage event", and fixes no outcome for a damage smaller than
280	 * the deductible. A deductible reduces a reimbursement; it does not bill the
281	 * claimant, so a damage at or below it is reimbursed at nothing rather than
282	 * at a negative amount. Settle it against the MHPCO before relying on it.
283	 */
284	function reimbursementAfterDeductible(damage: Damage, damagedItem: Item): number {
285	  const excessOverDeductible = reimbursableDamage(damage, damagedItem) - DEDUCTIBLE_PER_DAMAGE;
286	  return Math.max(excessOverDeductible, 0);
287	}
288	
289	interface ClaimResult {
290	  payout: number;
291	  remainingCap: number;
292	}
293	
294	/**
295	 * Settling an incident both pays the claimant and uses up part of the cap the
296	 * policy carries for the rest of its life, so the settled policy is the second
297	 * half of the outcome rather than a side effect: a claim leaves the policy in a
298	 * new state, and later claims against it see that state.
299	 */
300	/** The insured item a damage entry refers to. */
301	function damagedItemIn(policy: Policy, damage: Damage): Item {
302	  const item = policy.insuredItems.find((insured) => insured.type === damage.itemType);
303	  if (item === undefined) {
304	    throw new Error(`The policy covers no item of type "${damage.itemType}".`);
305	  }
306	  return item;
307	}
308	
309	function settleClaim(policy: Policy, incident: Incident): { result: ClaimResult; policy: Policy } {
310	  const payout = incident.damages.reduce(
311	    (sum, damage) => sum + reimbursementAfterDeductible(damage, damagedItemIn(policy, damage)),
312	    0,
313	  );
314	  const settled: Policy = { ...policy, remainingCap: policy.remainingCap - payout };
315	  return { result: { payout, remainingCap: settled.remainingCap }, policy: settled };
316	}
317	
318	export function runScenario(scenario: Scenario): ScenarioResults {
319	  /** Policies opened so far, addressed the way the input does: by the index of the quote step that opened each. */
320	  const policies = new Map<number, Policy>();
321	
322	  /**
323	   * A claim naming a step that opened no policy is outside the specification --
324	   * no example and no test describes it -- so this guard exists only to keep the
325	   * lookup total for the type system.
326	   */
327	  const policyOpenedBy = (quoteStepIndex: number): Policy => {
328	    const policy = policies.get(quoteStepIndex);
329	    if (policy === undefined) {
330	      throw new Error(`No policy was created by step ${String(quoteStepIndex)}.`);
331	    }
332	    return policy;
333	  };
334	
335	  const results = scenario.steps.map((step, stepIndex) => {
336	    if (step.op === "claim") {
337	      const { result, policy } = settleClaim(policyOpenedBy(step.policy), step.incident);
338	      policies.set(step.policy, policy);
339	      return result;
340	    }
341	    policies.set(stepIndex, openPolicy(step.items));
342	    return {
343	      premium: quotePremium(step.items, scenario.customer, contractOrdinalOfStep(stepIndex)),
344	    };
345	  });
346	  return { results };
347	}
